// === NORMALIZE INPUT & LOAD HISTORY ===
const telegramData = $input.first().json;
const username = telegramData.message?.from?.username || telegramData.message?.from?.first_name || 'User';
const message = telegramData.message?.text || '';
const chatId = telegramData.message?.chat?.id;

if (!message) {
  return { json: { error: 'No message text', chatId } };
}

// Load conversation history and memory from workflow static data
let conversationHistory = [];
let botMemory = '';

try {
  const workflowData = $workflow.getStaticData();
  conversationHistory = workflowData.conversationHistory || [];
  botMemory = workflowData.botMemory || '';
} catch (e) {
  console.log('Initializing new conversation');
}

// Add user message to history
conversationHistory.push({
  role: 'user',
  content: `${username}: ${message}`,
  timestamp: Date.now()
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory = conversationHistory.slice(-20);
}

console.log('=== NORMALIZE INPUT ===');
console.log('User Message:', message);
console.log('Chat ID:', chatId);
console.log('Username:', username);

return {
  json: {
    username,
    message,
    chatId,
    conversationHistory,
    botMemory,
    timestamp: Date.now(),
    source: 'normalize'
  }
};

// Process status data and forward normalize data
const normalizeData = $('Normalize Input').first().json;
const statusResponse = $input.first().json;

console.log('=== GET BOT STATUS ===');
console.log('Status response:', statusResponse);

return {
  json: {
    ...normalizeData,
    statusData: statusResponse,
    source: 'status_processed'
  }
};

// Process inventory data and forward previous data
const previousData = $('Process Status').first().json;
const inventoryResponse = $input.first().json;

console.log('=== GET BOT INVENTORY ===');
console.log('Inventory response:', inventoryResponse);

return {
  json: {
    ...previousData,
    inventoryData: inventoryResponse,
    source: 'final_data'
  }
};

// === BUILD AI PROMPT WITH FULL CAPABILITY AWARENESS ===
const data = $input.first().json;

console.log('=== BUILD AI PROMPT ===');
console.log('Received data source:', data.source);

// Extract user data (from normalize)
const username = data.username || 'User';
const message = data.message || '';
const chatId = data.chatId;
const conversationHistory = data.conversationHistory || [];
const botMemory = data.botMemory || '';

console.log('User Message:', message);
console.log('Chat ID:', chatId);
console.log('Username:', username);

// Extract bot status
const statusData = data.statusData;
let botStatus = 'Status unavailable';
if (statusData) {
  console.log('Status data available:', Object.keys(statusData));
  if (statusData.position) {
    botStatus = `Position: ${statusData.position.x}, ${statusData.position.y}, ${statusData.position.z} | Health: ${statusData.health}/20 | Action: ${statusData.current_action || 'Idle'}`;
  } else if (statusData.x !== undefined) {
    botStatus = `Position: ${statusData.x}, ${statusData.y}, ${statusData.z} | Health: ${statusData.health || 20}/20 | Action: ${statusData.current_action || 'Idle'}`;
  } else {
    botStatus = JSON.stringify(statusData).substring(0, 100);
  }
} else {
  console.log('No status data received');
}

// Extract inventory
const inventoryData = data.inventoryData;
let botInventory = 'Inventory unavailable';
if (inventoryData) {
  console.log('Inventory data available:', Object.keys(inventoryData));
  console.log('Inventory data type:', typeof inventoryData);
  console.log('Inventory data sample:', JSON.stringify(inventoryData).substring(0, 200));

  // Handle different inventory data structures safely
  if (inventoryData.inventory && Array.isArray(inventoryData.inventory)) {
    botInventory = inventoryData.inventory.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  } else if (Array.isArray(inventoryData)) {
    botInventory = inventoryData.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  } else if (inventoryData.data && Array.isArray(inventoryData.data)) {
    botInventory = inventoryData.data.map(item => `${item.name || item.type}(${item.count || item.quantity || 1})`).join(', ');
  } else if (typeof inventoryData === 'object') {
    // If it's an object but not the expected structure, show what we have
    botInventory = `Raw data: ${JSON.stringify(inventoryData).substring(0, 100)}...`;
  } else {
    botInventory = `Unexpected format: ${typeof inventoryData}`;
  }
} else {
  console.log('No inventory data received');
}

console.log('Final status:', botStatus);
console.log('Final inventory:', botInventory);

// Build comprehensive system prompt based on actual code capabilities
const systemPrompt = `You are a helpful Minecraft assistant. You can see, move, mine, build, craft, and interact with the world by using commands. You also have access to vision. Use vision when you're unsure what's in front of you, looking for resources, verifying something built, or navigating new areas. Your goal is to assist the user efficiently and accurately.

Speak concisely and avoid unnecessary filler. Do not act playful or in-character. Do not apologize unless something is truly wrong. Focus on being useful and responsive. When asked about your limitations, be honest and factual.

You must respond with a structured JSON output that contains an intent and parameters. Use these exact intents based on what the user wants:

MOVEMENT INTENTS:
- "move" - Move to coordinates or direction (params: x, y, z OR direction)
- "goToPlayer" - Go to a specific player (params: player, closeness)
- "followPlayer" - Follow a player (params: player, distance)
- "moveAway" - Move away from threats (params: distance)
- "searchForBlock" - Find specific blocks (params: block, range)
- "searchForEntity" - Find entities/players (params: entity, range)

BLOCK OPERATION INTENTS:
- "collectBlocks" - Mine/collect blocks (params: block, quantity)
- "placeBlocks" - Place blocks at location (params: material, x, y, z, face)
- "digDown" - Mine downward (params: depth)
- "activate" - Use blocks/buttons/levers (params: x, y, z)

ITEM MANAGEMENT INTENTS:
- "equip" - Equip items/armor (params: item)
- "discard" - Drop unwanted items (params: item, quantity)
- "consume" - Eat food/drink potions (params: item, quantity)
- "givePlayer" - Transfer items to players (params: player, item, quantity)

CHEST OPERATIONS INTENTS:
- "putInChest" - Store items in chest (params: item, quantity, x, y, z)
- "takeFromChest" - Retrieve items from chest (params: item, quantity, x, y, z)
- "viewChest" - Check chest contents (params: x, y, z)

CRAFTING INTENTS:
- "craft" - Craft recipes (params: item, quantity)
- "smelt" - Smelt items in furnace (params: item, quantity)
- "clearFurnace" - Clean furnaces

COMBAT INTENTS:
- "attackPlayer" - Engage in combat (params: player)
- "defendSelf" - Defensive actions (params: range)

MEMORY & NAVIGATION INTENTS:
- "rememberHere" - Save current location (params: name)
- "goToRememberedPlace" - Return to saved places (params: name)
- "savedPlaces" - List saved locations

INFORMATION INTENTS:
- "nearbyBlocks" - Scan environment
- "craftable" - Check craftable items  
- "entities" - List nearby entities
- "modes" - Check bot modes
- "getCraftingPlan" - Calculate crafting requirements (params: item, quantity)
- "stats" - Get bot status
- "inventory" - Check inventory

MODE MANAGEMENT INTENTS:
- "setMode" - Toggle bot behaviors (params: mode, enabled)
- "stay" - Wait/pause actions (params: seconds)
- "goToBed" - Sleep functionality

UTILITY INTENTS:
- "useDoor" - Operate doors (params: x, y, z optional)
- "newAction" - Custom AI actions (params: prompt)
- "lookAtPlayer" - Vision system (params: player, direction)
- "lookAtPosition" - Look at coordinates (params: x, y, z)

COMMUNICATION INTENTS:
- "startConversation" - Begin bot conversations (params: player, message)
- "endConversation" - End conversations (params: player)

CONTROL INTENTS:
- "restart" - Restart the agent
- "clearChat" - Clear chat history
- "endGoal" - Stop current goals
- "stop" - Force stop all actions
- "chat" - Simple conversation response (params: response)

Current Status: ${botStatus}
Current Inventory: ${botInventory}  
Summarized Memory: ${botMemory}

User said: "${message}"

You must respond with valid JSON in this exact format:
{
  "intent": "intentName",
  "params": {
    "paramName": "value"
  },
  "response": "Brief response message"
}

If you're unsure what the user wants, use the "chat" intent with a clarifying question. Always use specific parameter names that match the API handlers.`;

return {
  json: {
    systemPrompt,
    userMessage: message,
    username,
    message,
    chatId,
    conversationHistory,
    botMemory,
    botStatus,
    botInventory
  }
};

// === PARSE & VALIDATE AI RESPONSE ===
const aiResponse = $input.first().json.message?.content || $input.first().json.text || '';
const promptData = $('Build AI Prompt').first().json;

console.log('AI Response:', aiResponse);
console.log('User message:', promptData.message);

let parsedIntent = null;

try {
  // Extract JSON from AI response (handle markdown code blocks)
  let jsonStr = aiResponse.trim();

  // Remove markdown code blocks if present
  if (jsonStr.includes('```json')) {
    jsonStr = jsonStr.split('```json')[1].split('```')[0].trim();
  } else if (jsonStr.includes('```')) {
    jsonStr = jsonStr.split('```')[1].split('```')[0].trim();
  }

  // Try to find JSON object in the response
  const jsonMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[0];
  }

  parsedIntent = JSON.parse(jsonStr);

  // Validate required fields
  if (!parsedIntent.intent || !parsedIntent.response) {
    throw new Error('Missing required fields: intent or response');
  }

  // Ensure params exists
  if (!parsedIntent.params) {
    parsedIntent.params = {};
  }

  console.log('Successfully parsed intent:', parsedIntent.intent);
  console.log('Successfully parsed params:', JSON.stringify(parsedIntent.params));

} catch (error) {
  console.error('Failed to parse AI response:', error.message);
  console.error('Raw AI response:', aiResponse);

  // ENHANCED FALLBACK: Pattern matching based on user message
  const message = promptData.message.toLowerCase();

  // Inventory patterns
  if (message.match(/(inventory|what.*have|what.*carrying|items|stuff)/)) {
    parsedIntent = {
      intent: 'inventory',
      params: {},
      response: 'Let me check my inventory...'
    };
  }
  // Status patterns
  else if (message.match(/(status|health|how.*you|where.*you|position)/)) {
    parsedIntent = {
      intent: 'status',
      params: {},
      response: 'Checking my status...'
    };
  }
  // Movement patterns
  else if (message.match(/(move|go|walk|run|travel)\s+(left|right|forward|back|north|south|east|west)/)) {
    const directionMatch = message.match(/(left|right|forward|back|north|south|east|west)/);
    const direction = directionMatch ? directionMatch[1] : 'forward';
    console.log('FALLBACK: Matched movement pattern, direction:', direction);
    parsedIntent = {
      intent: 'move',
      params: { direction: direction },
      response: `Moving ${direction}!`
    };
  }
  // Coordinate movement
  else if (message.match(/(move|go|travel).*(\d+).*(\d+).*(\d+)/)) {
    const coords = message.match(/(\d+)\s+(\d+)\s+(\d+)/);
    if (coords) {
      parsedIntent = {
        intent: 'move',
        params: { x: parseInt(coords[1]), y: parseInt(coords[2]), z: parseInt(coords[3]) },
        response: `Moving to coordinates ${coords[1]}, ${coords[2]}, ${coords[3]}!`
      };
    }
  }
  // Collection patterns
  else if (message.match(/(collect|get|mine|gather|pick)/)) {
    parsedIntent = {
      intent: 'collect',
      params: { block: 'dirt', quantity: 10 },
      response: 'Collecting blocks!'
    };
  }
  // Place patterns
  else if (message.match(/(place|put|build)/)) {
    parsedIntent = {
      intent: 'place',
      params: { material: 'dirt' },
      response: 'Placing a block!'
    };
  }
  // Stop patterns
  else if (message.match(/(stop|halt|cease|end)/)) {
    parsedIntent = {
      intent: 'stop',
      params: {},
      response: 'Stopping my current action!'
    };
  }
  // Default to chat
  else {
    parsedIntent = {
      intent: 'chat',
      params: {},
      response: aiResponse || "I didn't quite understand that. Can you be more specific?"
    };
  }

  console.log('Used fallback parsing, intent:', parsedIntent.intent);
}

// Skip validation for movement with direction (doesn't need coordinates)
const intent = parsedIntent.intent;
const params = parsedIntent.params;
let validationError = null;

switch (intent) {
  case 'move':
    console.log('VALIDATION: Move intent with params:', JSON.stringify(params));
    // Allow either coordinates OR direction
    if (!params.direction && (params.x === undefined || params.y === undefined || params.z === undefined)) {
      console.log('VALIDATION: Move validation failed - no direction and incomplete coordinates');
      validationError = 'Missing coordinates or direction for move command';
    } else {
      console.log('VALIDATION: Move validation passed');
    }
    break;
  case 'collect':
    if (!params.block) {
      params.block = 'dirt'; // Default block
      params.quantity = params.quantity || 10;
    }
    break;
  case 'place':
    if (!params.material) {
      params.material = 'dirt'; // Default material
    }
    break;
}

if (validationError) {
  console.error('Validation error:', validationError);
  parsedIntent.intent = 'unknown';
  parsedIntent.response = `I need more information: ${validationError}`;
}

console.log('Final intent:', parsedIntent.intent, 'params:', parsedIntent.params);
console.log('Will this go to clarification? Intent is unknown/chat:', (parsedIntent.intent === 'unknown' || parsedIntent.intent === 'chat'));

return {
  json: {
    ...parsedIntent,
    chatId: promptData.chatId,
    username: promptData.username,
    originalMessage: promptData.message,
    conversationHistory: promptData.conversationHistory,
    botMemory: promptData.botMemory,
    rawAiResponse: aiResponse
  }
};

// === SAVE CONVERSATION & SEND REPLY ===
const data = $input.first().json;

console.log('Save & Reply - Input data:', JSON.stringify(data, null, 2));

// Ensure we have a valid chatId
if (!data.chatId) {
  console.error('Missing chatId in Save & Reply node');
  console.log('Available data keys:', Object.keys(data));
} else {
  console.log('ChatId found:', data.chatId, 'Type:', typeof data.chatId);
}

// Save bot response to conversation history
const conversationHistory = data.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: data.response,
  timestamp: Date.now()
});

// Keep last 20 messages
if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

// Save to workflow static data
try {
  const workflowData = $workflow.getStaticData();
  workflowData.conversationHistory = conversationHistory;
  workflowData.botMemory = data.botMemory || '';
} catch (e) {
  console.error('Failed to save conversation history:', e);
}

console.log('Save & Reply - Final output chatId:', data.chatId, 'response:', data.response);

return {
  json: {
    chatId: data.chatId,
    text: data.response,
    conversationHistory
  }
};

// === FORMAT RESULT FOR USER ===
const intentData = $('Route by Intent').first().json;
const executionResult = $input.first().json;

let finalMessage = intentData.response;

// If execution failed, append error
if (executionResult.error) {
  finalMessage += `\n\n⚠️ Error: ${executionResult.error}`;
} else if (executionResult.message && executionResult.message !== intentData.response) {
  finalMessage += `\n\n✅ ${executionResult.message}`;
}

// For status/inventory, include the data
if (intentData.intent === 'status' && executionResult.position) {
  finalMessage += `\n\n📍 Position: ${executionResult.position.x}, ${executionResult.position.y}, ${executionResult.position.z}`;
  finalMessage += `\n❤️ Health: ${executionResult.health}/20`;
  finalMessage += `\n🍖 Hunger: ${executionResult.hunger}/20`;
  finalMessage += `\n⚙️ Action: ${executionResult.current_action || 'Idle'}`;
}

if (intentData.intent === 'inventory' && executionResult.inventory) {
  finalMessage += `\n\n🎒 ${executionResult.inventory}`;
}

// Save conversation history
const conversationHistory = intentData.conversationHistory || [];
conversationHistory.push({
  role: 'assistant',
  content: finalMessage,
  timestamp: Date.now()
});

if (conversationHistory.length > 20) {
  conversationHistory.splice(0, conversationHistory.length - 20);
}

try {
  const workflowData = $workflow.getStaticData();
  workflowData.conversationHistory = conversationHistory;
} catch (e) {
  console.error('Failed to save conversation:', e);
}

return {
  json: {
    chatId: intentData.chatId,
    text: finalMessage,
    conversationHistory
  }
};
